// --- scale_deployment / restart_pod (real remediation execution) ---

// scaleReplicaCeiling bounds how large a single ScaleDeployment patch may
// set /spec/replicas to — lld/08-remediation-contracts.md §3's own example
// of what this sane-bound check exists to catch ("reject a 0->500 jump as
// a plan-authoring bug, not a valid scale action"). Deliberately a fixed,
// generous ceiling rather than a proportional check against the object's
// current replica count: the agent has no reliable notion of "current"
// beyond what it's about to overwrite (the whole point of the
// resourceVersion precondition is that this may already be stale), so this
// stays a simple, absolute backstop — the real, current-aware bound check
// belongs where the current value is actually known firsthand, which is
// internal/api/approvals.go at the moment it fetches the fresh
// resourceVersion this same patch embeds.
const scaleReplicaCeiling = 1000

// restartablePodTemplateKinds is restart_pod's own, narrower requirement on
// top of supportedGVKs: a target whose /spec/template a strategic-merge
// patch can actually add an annotation under. A bare Pod (this action
// type's namesake) has no such field — internal/api/approvals.go is
// responsible for resolving a Pod target to its owning workload (via the
// existing get_owner_chain tool) before ever signing a plan, and this check
// is this file's own backstop against a plan that skipped that step, not
// something this tool call resolves itself.
var restartablePodTemplateKinds = map[string]bool{
	"Deployment":  true,
	"StatefulSet": true,
	"DaemonSet":   true,
}

// signedPlanArgs is the wire shape both scale_deployment and restart_pod
// take as their tool-call args: a full remediation.SignedPlan envelope,
// never a bare target+params pair — see this file's own header comment for
// why nothing reaches Patch without first being independently re-verified
// here, not merely trusted because it arrived over the tunnel.
type signedPlanArgs struct {
	Plan remediation.SignedPlan `json:"plan"`
}

// executeResult is both tools' successful result: the object's new
// resourceVersion, letting the caller (internal/api/approvals.go) record
// exactly what state it left the object in without a second read.
type executeResult struct {
	ResourceVersion string `json:"resourceVersion"`

	// DryRun echoes back whether this call actually ran as a server-side dry
	// run. It exists for one reason and it is not informational: it is the
	// hub's only way to distinguish "the agent rehearsed the change" from "an
	// agent too old to understand SignedPlan.DryRun ignored the field and
	// mutated the cluster for real". Without the echo those two cases are
	// indistinguishable — both return a 200 and a resourceVersion — and the
	// hub would go on to execute a second time. The hub therefore treats a
	// missing or false echo on a dry-run request as a failed gate. See
	// remediation.PlanContent.DryRun.
	DryRun bool `json:"dryRun,omitempty"`

	// Object is the object the API server produced, returned on a dry run
	// only. This is the authoritative "after" state — it has been through
	// defaulting, mutating admission webhooks and validation, so it is what
	// the cluster would really hold, not what ARGUS predicted it would hold.
	// BACKLOG.md F13's diff is computed against it rather than against a
	// hub-side simulation of the patch, which is the difference between
	// showing an operator a claim and showing them a result.
	//
	// Deliberately dry-run-only. On a real execution the same bytes would
	// double every response for the benefit of a post-change field check that
	// belongs to V1 and does not exist yet; when it does, it should re-read
	// the object rather than trust an echo of the write.
	//
	// Absent when the object exceeded maxDryRunObjectBytes or could not be
	// marshaled. A consumer must treat "no object" as "no diff available",
	// never as "nothing changed" — the attestation is valid either way.
	Object json.RawMessage `json:"object,omitempty"`

	// Patch is the strategic-merge patch body exactly as submitted, returned
	// on a dry run alongside Object. It lets the hub tell the fields THIS PLAN
	// asked to change from the fields the cluster changed as well — defaulting,
	// and mutating admission webhooks. That second set is the most valuable
	// thing a dry-run diff can surface to an approver, and it is knowable only
	// because Object comes from the API server rather than from applying the
	// patch hub-side.
	Patch json.RawMessage `json:"patch,omitempty"`
}

// applyPlanPatch is the single place any signed plan reaches the API server.
//
// It exists to centralize one decision that must not be re-made per action
// type: whether this call is a rehearsal or a mutation. Every execution tool
// in this file builds a strategic-merge patch and then submits it, and each of
// those call sites used to spell out the submission itself. That is exactly
// the shape where a fifth action type gets added, the author copies a
// neighbour, and the copy silently omits the dry-run option — a bug whose
// symptom is a "dry run" that changes the cluster. Threading it through one
// function makes forgetting impossible rather than merely unlikely.
//
// It also guarantees the property the whole gate rests on: the rehearsal and
// the real execution submit *byte-identical* patches to the same resource
// through the same code, differing only in PatchOptions. A gate that validated
// a separately-constructed patch would attest to something other than what
// later runs.
func (e *ToolExecutor) applyPlanPatch(ctx context.Context, gvr schema.GroupVersionResource, plan remediation.SignedPlan, patch []byte) (*unstructured.Unstructured, error) {
	opts := metav1.PatchOptions{}
	if plan.DryRun {
		opts.DryRun = []string{metav1.DryRunAll}
	}
	return e.dynamic.Resource(gvr).Namespace(plan.TargetNamespace).Patch(ctx, plan.TargetName, types.StrategicMergePatchType, patch, opts)
}

// maxDryRunObjectBytes bounds the dry-run object carried back for the diff.
//
// The tunnel refuses a message over 1 MiB (internal/gateway's
// maxTunnelMessageBytes), and the whole point of this bound is that exceeding
// it must never be able to break the GATE. An object big enough to blow the
// frame — a workload carrying an enormous last-applied-configuration
// annotation, say — would otherwise turn "the cluster accepted this change"
// into a transport failure that reads as a rejection. So the diff payload is
// dropped well before that limit and the attestation still lands. 256 KiB is
// roughly two orders of magnitude above a normal Deployment.
const maxDryRunObjectBytes = 256 << 10

// planPatchResult builds the tool result for a completed patch, dry or real.
func planPatchResult(plan remediation.SignedPlan, patched *unstructured.Unstructured, patch []byte) json.RawMessage {
	res := executeResult{ResourceVersion: patched.GetResourceVersion(), DryRun: plan.DryRun}
	if plan.DryRun {
		// Every failure below degrades the DIFF and never the attestation. The
		// API server has already accepted the patch by this point, which is
		// the fact the gate needs; reporting a marshal or size problem as a
		// failed dry run would be a lie about the cluster, and a much more
		// expensive one than a missing diff.
		switch b, err := patched.MarshalJSON(); {
		case err != nil:
			logger.Warn("dry-run: could not marshal the resulting object for the diff",
				slog.String("action_type", string(plan.ActionType)), slog.String("namespace", plan.TargetNamespace), slog.String("name", plan.TargetName), logging.Err(err))
		case len(b) > maxDryRunObjectBytes:
			// Dropped whole rather than truncated: half a JSON object is not a
			// diffable object, and a hub that received one would have to guess
			// whether a missing field was unchanged or merely cut off.
			logger.Warn("dry-run: resulting object past the size cap; attesting without the diff payload",
				slog.String("action_type", string(plan.ActionType)), slog.String("namespace", plan.TargetNamespace), slog.String("name", plan.TargetName), slog.Int("object_bytes", len(b)), slog.Int("cap_bytes", maxDryRunObjectBytes))
		default:
			res.Object = b
		}
		// The patch exactly as submitted. The hub uses it to separate "what
		// this plan asked for" from "what the cluster did in addition"
		// (defaulting, mutating webhooks) — which is the most valuable thing a
		// dry-run diff can show, and is only knowable because the after-state
		// comes from the API server rather than from a hub-side simulation.
		// Sourced from the agent because the agent is the authority on what it
		// actually sent; a hub-side re-derivation from action type and params
		// would be a second thing to be wrong.
		res.Patch = patch
	}
	return mustMarshal(res)
}

// verifySignedPlan is the shared preflight scale_deployment and restart_pod
// both run before ever calling Patch: this agent must have a remediation
// identity at all (SetRemediationCredentials), the envelope's own
// ActionType must match the tool it was sent to (a ScaleDeployment
// envelope can never execute as a restart even if otherwise validly
// signed), the signature must independently re-verify against this agent's
// own persisted per-cluster key (never a key the caller supplies — this
// function has no parameter for one), and the target must resolve to a
// supported GVK.
func (e *ToolExecutor) verifySignedPlan(rawArgs json.RawMessage, wantAction remediation.ActionType) (remediation.SignedPlan, schema.GroupVersionResource, error) {
	if e.clusterID == "" || len(e.planSigningKey) == 0 {
		return remediation.SignedPlan{}, schema.GroupVersionResource{}, errors.New("this agent has no remediation credentials — re-enroll to obtain a plan signing key")
	}
	var args signedPlanArgs
	if err := json.Unmarshal(rawArgs, &args); err != nil {
		return remediation.SignedPlan{}, schema.GroupVersionResource{}, fmt.Errorf("invalid args: %w", err)
	}
	if args.Plan.ActionType != wantAction {
		return remediation.SignedPlan{}, schema.GroupVersionResource{}, fmt.Errorf("signed plan action type %q does not match the tool it was sent to (%q)", args.Plan.ActionType, wantAction)
	}
	if err := remediation.Verify(args.Plan, e.clusterID, e.planSigningKey, time.Now()); err != nil {
		return remediation.SignedPlan{}, schema.GroupVersionResource{}, err
	}
	// CreateResource is the one action type with a legitimate empty
	// ResourceVersion: its target does not exist yet, so there is no live
	// object to fetch a precondition from — createResource's own precondition
	// is "this object does not already exist", checked by create_resource
	// itself via a Get-before-Create, not by a resourceVersion match. Every
	// other action type still requires one: an empty value for any of them
	// means the hub's fetchPreconditionWithObject was skipped or failed
	// silently, which must never be treated as "no precondition needed."
	if args.Plan.ResourceVersion == "" && wantAction != remediation.ActionCreateResource {
		return remediation.SignedPlan{}, schema.GroupVersionResource{}, errors.New("signed plan is missing its resourceVersion precondition")
	}
	gvk, err := parseGVKString(args.Plan.TargetGVK)
	if err != nil {
		return remediation.SignedPlan{}, schema.GroupVersionResource{}, err
	}
	res, ok := supportedGVKs[gvk]
	if !ok {
		return remediation.SignedPlan{}, schema.GroupVersionResource{}, fmt.Errorf("unsupported gvk %q", args.Plan.TargetGVK)
	}
	return args.Plan, res.gvr, nil
}

// scaleDeployment implements lld/08 §3's scaleWorkload: a strategic-merge
// Patch touching /spec/replicas only, with the resourceVersion precondition
// embedded directly in the same patch body (lld/08 §5, SR-20) rather than a
// separate Get-then-Patch pair.
func (e *ToolExecutor) scaleDeployment(ctx context.Context, rawArgs json.RawMessage) (json.RawMessage, bool, error) {
	plan, gvr, err := e.verifySignedPlan(rawArgs, remediation.ActionScaleDeployment)
	if err != nil {
		return nil, false, err
	}
	if gvr.Resource != "deployments" && gvr.Resource != "statefulsets" {
		return nil, false, fmt.Errorf("scale_deployment does not support target resource %q", gvr.Resource)
	}

	var params struct {
		Replicas int `json:"replicas"`
	}
	if err := json.Unmarshal(plan.Params, &params); err != nil {
		return nil, false, fmt.Errorf("invalid scale deployment params: %w", err)
	}
	if params.Replicas < 0 || params.Replicas > scaleReplicaCeiling {
		return nil, false, fmt.Errorf("replicas %d is outside the allowed range [0, %d]", params.Replicas, scaleReplicaCeiling)
	}

	patch, err := json.Marshal(map[string]any{
		"metadata": map[string]any{"resourceVersion": plan.ResourceVersion},
		"spec":     map[string]any{"replicas": params.Replicas},
	})
	if err != nil {
		return nil, false, fmt.Errorf("build patch: %w", err)
	}

	patched, err := e.applyPlanPatch(ctx, gvr, plan, patch)
	if err != nil {
		return nil, false, sanitizeK8sErr(err)
	}
	return planPatchResult(plan, patched, patch), false, nil
}

// resourceLimitPatchableResources is patch_resource_limits' own narrowing on
// top of supportedGVKs, and it is deliberately narrower than
// restartablePodTemplateKinds: DaemonSets are excluded because neither the
// argus-remediate ClusterRole nor the ValidatingAdmissionPolicy
// (deploy/helm/argus-agent/templates) covers them, so a DaemonSet patch could
// only ever end in a 403 from the API server. Keyed by plural resource, since
// that is what verifySignedPlan returns and what the dynamic client indexes
// by.
var resourceLimitPatchableResources = map[string]bool{
	"deployments":  true,
	"statefulsets": true,
}

// patchResourceLimits implements ActionPatchResourceLimits: a strategic-merge
// Patch setting ONE named container's cpu/memory requests and limits under
// /spec/template/spec/containers, with the same embedded-resourceVersion
// precondition as the two tools above (lld/08 §5, SR-20).
//
// Why a strategic-merge patch and not a JSON patch by container index: the
// containers list has `name` as its strategic merge key, so a body naming the
// container merges into that container and leaves every sibling — and every
// other field of the same container, including its image and security
// context — untouched, with no index for a concurrent change to invalidate. A
// JSON patch would need /spec/template/spec/containers/3/resources, and index
// 3 stops meaning the same container the moment anybody reorders the list.
// The same merge-key behaviour is also why the container-existence check
// below is mandatory rather than defensive: a merge key that matches nothing
// APPENDS, so a plan naming a container that does not exist would silently
// add a new, imageless container to the workload's pod template.
//
// Four independent things must hold before the Patch is issued, and this
// function checks the last three (the first is RBAC, enforced elsewhere):
//  1. The agent runs under the opt-in argus-remediate identity (chart).
//  2. The envelope verifies against this agent's own persisted per-cluster
//     key, names this exact action type, and has not expired
//     (verifySignedPlan).
//  3. The params satisfy the same absolute bounds the hub used —
//     re-validated here from the shared
//     remediation.PatchResourceLimitsParams.Validate, never trusted because
//     the hub said so (§10.3's agent-side re-validation: "even a fully
//     compromised hub cannot make an agent" exceed local guardrails).
//  4. A pre-computed rollback is present in the signed envelope, and the live
//     object still matches what that rollback claims to restore.
func (e *ToolExecutor) patchResourceLimits(ctx context.Context, rawArgs json.RawMessage) (json.RawMessage, bool, error) {
	plan, gvr, err := e.verifySignedPlan(rawArgs, remediation.ActionPatchResourceLimits)
	if err != nil {
		return nil, false, err
	}
	if !resourceLimitPatchableResources[gvr.Resource] {
		return nil, false, fmt.Errorf("patch_resource_limits does not support target resource %q (Deployment and StatefulSet only)", gvr.Resource)
	}

	var params remediation.PatchResourceLimitsParams
	if err := json.Unmarshal(plan.Params, &params); err != nil {
		return nil, false, fmt.Errorf("invalid patch resource limits params: %w", err)
	}
	if err := params.Validate(); err != nil {
		return nil, false, fmt.Errorf("agent-side re-validation rejected this plan: %w", err)
	}

	// A rollback is MANDATORY for this action type, and its absence is an
	// error rather than a shrug. DESIGN.md §10.3 requires the
	// compensating action to be captured before execution; the hub is what
	// captures it (it is the side that reads the live values), so from here
	// the only way to enforce "it really was captured" is to refuse to
	// execute without it. Because Rollback is inside the signature, this also
	// distinguishes "the hub captured nothing" from "something stripped it in
	// transit" — stripping it changes planHash and fails verification above.
	if plan.Rollback == nil {
		return nil, false, errors.New("signed plan carries no rollback: this action requires a pre-computed compensating action captured from live state before execution")
	}
	if plan.Rollback.ActionType != remediation.ActionPatchResourceLimits {
		return nil, false, fmt.Errorf("signed plan's rollback is a %q, which cannot undo a PatchResourceLimits", plan.Rollback.ActionType)
	}
	var rollbackParams remediation.PatchResourceLimitsParams
	if err := json.Unmarshal(plan.Rollback.Params, &rollbackParams); err != nil {
		return nil, false, fmt.Errorf("invalid rollback params: %w", err)
	}
	// ValidateRestore, not Validate: a compensating action records values read
	// off this very object, so the absolute minimums written for a PROPOSED
	// value do not apply to it (see
	// remediation.PatchResourceLimitsParams.ValidateRestore — a container
	// legitimately living under a 4Mi limit has an undo that says 4Mi, and
	// rejecting that made raising the limit impossible). This is not a hole in
	// point 3's agent-side re-validation above: the forward params still go
	// through the full Validate, and these rollback params are never applied
	// here — the patch body below is built from params only, and an
	// operator-initiated undo arrives as its own forward plan.
	if err := rollbackParams.ValidateRestore(); err != nil {
		return nil, false, fmt.Errorf("the plan's rollback is not itself a valid plan: %w", err)
	}
	if rollbackParams.Container != params.Container {
		return nil, false, fmt.Errorf("the plan's rollback targets container %q but the plan changes container %q", rollbackParams.Container, params.Container)
	}

	// Read the live object before mutating it. Three things this buys, none
	// of which the hub's own earlier read can provide (that read happened on
	// the other side of a tunnel, at a moment this agent cannot vouch for):
	//   - the named container demonstrably exists, so the merge-key append
	//     described above cannot happen;
	//   - the resourceVersion the plan was signed against is still the live
	//     one, so a stale plan fails here with a clear message instead of as
	//     a bare 409 from the API server;
	//   - the rollback the hub captured still describes reality.
	// The read-then-patch window is closed by the resourceVersion embedded in
	// the patch body itself: if anything changes the object between this Get
	// and the Patch below, the API server rejects the Patch rather than
	// applying it to a world this check never saw.
	live, err := e.dynamic.Resource(gvr).Namespace(plan.TargetNamespace).Get(ctx, plan.TargetName, metav1.GetOptions{})
	if err != nil {
		return nil, false, sanitizeK8sErr(err)
	}
	if live.GetResourceVersion() != plan.ResourceVersion {
		return nil, false, fmt.Errorf("the target has changed since this plan was signed (resourceVersion %s, plan expected %s) — refusing to apply a plan whose preconditions no longer hold", live.GetResourceVersion(), plan.ResourceVersion)
	}
	if err := verifyLiveContainerResources(live, params, rollbackParams); err != nil {
		return nil, false, err
	}

	resources := map[string]any{}
	if limits := quantityMap(params.CPULimit, params.MemoryLimit); len(limits) > 0 {
		resources["limits"] = limits
	}
	if requests := quantityMap(params.CPURequest, params.MemoryRequest); len(requests) > 0 {
		resources["requests"] = requests
	}
	patch, err := json.Marshal(map[string]any{
		"metadata": map[string]any{"resourceVersion": plan.ResourceVersion},
		"spec": map[string]any{
			"template": map[string]any{
				"spec": map[string]any{
					"containers": []any{
						map[string]any{
							"name":      params.Container,
							"resources": resources,
						},
					},
				},
			},
		},
	})
	if err != nil {
		return nil, false, fmt.Errorf("build patch: %w", err)
	}

	patched, err := e.applyPlanPatch(ctx, gvr, plan, patch)
	if err != nil {
		return nil, false, sanitizeK8sErr(err)
	}
	return planPatchResult(plan, patched, patch), false, nil
}

// quantityMap builds one limits/requests map from the two optional
// quantities, omitting whichever is unset. An empty result means "this half
// of the patch says nothing", which is why the caller checks len() before
// adding the key: a `"limits": {}` in a strategic-merge body is a no-op, but
// an explicit empty object in a patch is the kind of thing that reads as
// intent to a future maintainer, and there is none here.
func quantityMap(cpu, memory string) map[string]any {
	m := map[string]any{}
	if cpu != "" {
		m["cpu"] = cpu
	}
	if memory != "" {
		m["memory"] = memory
	}
	return m
}

// verifyLiveContainerResources checks the live object against the plan: the
// named container must exist, and every field the plan sets must currently
// hold exactly what the plan's rollback says it will restore.
//
// The second half is the interesting one. It is not a duplicate of the hub's
// own bound check (internal/api/remediation_exec.go's
// checkResourceLimitsBound) — that decided whether the CHANGE is acceptable,
// using rules this agent has no business re-litigating. This decides whether
// the UNDO is still true, which is a different question with a different
// failure mode: a rollback that describes a state the object is no longer in
// is worse than no rollback at all, because it would be applied confidently.
// It also happens to catch the case the resourceVersion check cannot — a hub
// that computed the rollback from a different object than the one it signed
// the plan for.
//
// Note what is NOT re-checked here: whether raising this limit is a good
// idea, whether the workload will schedule, whether the operator meant it.
// Those are hub-side and human-side decisions. The agent's job is to refuse
// what is structurally unsafe, not to second-guess an approved plan.
func verifyLiveContainerResources(live *unstructured.Unstructured, params, rollback remediation.PatchResourceLimitsParams) error {
	containers, found, err := unstructured.NestedSlice(live.Object, "spec", "template", "spec", "containers")
	if err != nil || !found {
		return errors.New("the live object has no readable spec.template.spec.containers — refusing to patch container resources on an object whose shape could not be read")
	}
	for _, raw := range containers {
		c, ok := raw.(map[string]any)
		if !ok {
			return errors.New("the live object has a malformed container entry — refusing to patch without being able to read every container")
		}
		if name, _ := c["name"].(string); name != params.Container {
			continue
		}
		// Absent maps read as empty, which is correct: a container with no
		// resources block has no current value for any of these, and the
		// mismatch check below then fails closed with a clear message rather
		// than a nil-map panic. A PRESENT-but-unreadable map is different and
		// is an error, not an empty map — NestedStringMap only errors when a
		// value there is not a string, which for a quantity field means we are
		// misreading the object, and "misread" must not collapse into "unset".
		limits, _, limitsErr := unstructured.NestedStringMap(c, "resources", "limits")
		requests, _, requestsErr := unstructured.NestedStringMap(c, "resources", "requests")
		if limitsErr != nil || requestsErr != nil {
			return fmt.Errorf("container %q's live resources could not be read as quantity strings — refusing to patch an object we are misreading", params.Container)
		}
		for _, f := range []struct {
			label      string
			set        string
			expectLive string
			liveValue  string
		}{
			{"memory limit", params.MemoryLimit, rollback.MemoryLimit, limits["memory"]},
			{"memory request", params.MemoryRequest, rollback.MemoryRequest, requests["memory"]},
			{"CPU limit", params.CPULimit, rollback.CPULimit, limits["cpu"]},
			{"CPU request", params.CPURequest, rollback.CPURequest, requests["cpu"]},
		} {
			if f.set == "" {
				continue
			}
			if f.liveValue == "" {
				return fmt.Errorf("container %q has no %s set on the live object, and this action never introduces one", params.Container, f.label)
			}
			if f.liveValue != f.expectLive {
				return fmt.Errorf("container %q's live %s is %s, but this plan's rollback claims it is %s — refusing to make a change whose recorded undo does not match reality", params.Container, f.label, f.liveValue, f.expectLive)
			}
		}
		return nil
	}
	return fmt.Errorf("no container named %q on the live object — refusing to execute, because a strategic-merge patch keyed on an unmatched container name would ADD a container rather than change one", params.Container)
}

// --- revert_container_image ---

// replicaSetGVR is the resource revert_container_image reads to verify a revert
// target against the workload's own rollout history. Spelled out here rather
// than looked up through supportedGVKs because this is not a caller-supplied
// GVK being validated — it is a fixed, internal read this tool always makes,
// and both the read-only argus-investigate ClusterRole and the opt-in
// argus-remediate pack already grant get/list/watch on it (deploy/helm/
// argus-agent/templates/clusterrole.yaml, where ReplicaSets are deliberately
// read-only in BOTH roles: this tool reads history, it never writes a
// ReplicaSet).
var replicaSetGVR = schema.GroupVersionResource{Group: "apps", Version: "v1", Resource: "replicasets"}

// revertContainerImage implements ActionRevertContainerImage: a strategic-merge
// Patch setting ONE named container's `image` under
// /spec/template/spec/containers, with the same embedded-resourceVersion
// precondition as the three tools above (lld/08 §5, SR-20).
//
// The patch mechanism is the same merge-key body patchResourceLimits explains
// at length (container `name` is the strategic merge key, so a body naming one
// container leaves its siblings and every other field of that container
// untouched, and an unmatched name APPENDS rather than failing). What differs is
// what has to be true before it is issued, because the value being written is
// not a number a bound can contain — it is an image reference, i.e. code that
// will run in the customer's cluster.
//
// Five things must hold, and this function checks four of them (the first is
// RBAC, enforced elsewhere):
//  1. The agent runs under the opt-in argus-remediate identity (chart).
//  2. The envelope verifies against this agent's own persisted per-cluster key,
//     names this exact action type, and has not expired (verifySignedPlan).
//  3. The params and the pre-computed rollback are both well-formed by the same
//     shared definition the hub used (remediation.
//     RevertContainerImageExecParams.Validate), the rollback names the same
//     container, and the rollback's image still matches what the container is
//     actually running — the same "is the recorded undo still true" check
//     patch_resource_limits makes, for the same reason: a confidently-applied
//     rollback that describes a state the object was never in is worse than
//     none.
//  4. THE IMAGE PROVABLY RAN HERE. The image this plan wants to set must appear
//     as this container's image in at least one ReplicaSet the target
//     Deployment owns. This is the check that makes the action's central claim
//     ("the previous image demonstrably ran") an enforced property rather than
//     a hub-side promise, and it is deliberately not a re-derivation of the
//     hub's choice: the agent does NOT recompute which revision is "previous",
//     does not compare revision numbers, and does not second-guess an approved
//     plan (the same division of labour verifyLiveContainerResources' doc
//     comment draws). It answers exactly one question — is this image in this
//     workload's own history — because that is the question a signature cannot
//     answer, and the one whose wrong answer means arbitrary code.
func (e *ToolExecutor) revertContainerImage(ctx context.Context, rawArgs json.RawMessage) (json.RawMessage, bool, error) {
	plan, gvr, err := e.verifySignedPlan(rawArgs, remediation.ActionRevertContainerImage)
	if err != nil {
		return nil, false, err
	}
	// Deployments only, and unlike patch_resource_limits' exclusion of
	// DaemonSet this is not about RBAC: a StatefulSet's or DaemonSet's revision
	// history lives in ControllerRevisions, which this agent cannot read and
	// which the admission policy does not open. Without the history there is no
	// way to run check (4), and this tool does not execute an image change it
	// cannot verify.
	if gvr.Resource != "deployments" {
		return nil, false, fmt.Errorf("revert_container_image does not support target resource %q (Deployment only — a Deployment's ReplicaSets are the rollout history this action verifies against)", gvr.Resource)
	}

	var params remediation.RevertContainerImageExecParams
	if err := json.Unmarshal(plan.Params, &params); err != nil {
		return nil, false, fmt.Errorf("invalid revert container image params: %w", err)
	}
	if err := params.Validate(); err != nil {
		return nil, false, fmt.Errorf("agent-side re-validation rejected this plan: %w", err)
	}

	// A rollback is MANDATORY here for the same reason it is for
	// patch_resource_limits (DESIGN.md §10.3 requires it to be
	// captured before execution, and the only way the agent can enforce "it
	// really was captured" is to refuse without it), plus one specific to this
	// action: the rollback IS the current image, so an envelope without one is
	// an envelope whose sender never read the state it is about to overwrite.
	if plan.Rollback == nil {
		return nil, false, errors.New("signed plan carries no rollback: this action requires a pre-computed compensating action naming the image the container is running now, captured from live state before execution")
	}
	if plan.Rollback.ActionType != remediation.ActionRevertContainerImage {
		return nil, false, fmt.Errorf("signed plan's rollback is a %q, which cannot undo a RevertContainerImage", plan.Rollback.ActionType)
	}
	var rollbackParams remediation.RevertContainerImageExecParams
	if err := json.Unmarshal(plan.Rollback.Params, &rollbackParams); err != nil {
		return nil, false, fmt.Errorf("invalid rollback params: %w", err)
	}
	if err := rollbackParams.Validate(); err != nil {
		return nil, false, fmt.Errorf("the plan's rollback is not itself a valid plan: %w", err)
	}
	if rollbackParams.Container != params.Container {
		return nil, false, fmt.Errorf("the plan's rollback targets container %q but the plan changes container %q", rollbackParams.Container, params.Container)
	}
	if rollbackParams.Image == params.Image {
		// Not merely a no-op: an envelope whose forward action and undo name the
		// same image is internally inconsistent, so whatever built it misread
		// the live state. Refuse rather than execute a patch that cannot be what
		// anyone intended.
		return nil, false, fmt.Errorf("this plan sets container %q to image %s and records the same image as its undo — refusing an internally inconsistent plan", params.Container, params.Image)
	}

	// Read the live object before mutating it, for the same three reasons
	// patchResourceLimits does (the container demonstrably exists, so the
	// merge-key append cannot happen; the resourceVersion is still the one the
	// plan was signed against; the recorded undo still describes reality), and
	// a fourth: the live object's UID is what makes the history check below an
	// ownership question rather than a name-prefix guess. The read-then-patch
	// window is closed by the resourceVersion embedded in the patch body itself.
	live, err := e.dynamic.Resource(gvr).Namespace(plan.TargetNamespace).Get(ctx, plan.TargetName, metav1.GetOptions{})
	if err != nil {
		return nil, false, sanitizeK8sErr(err)
	}
	if live.GetResourceVersion() != plan.ResourceVersion {
		return nil, false, fmt.Errorf("the target has changed since this plan was signed (resourceVersion %s, plan expected %s) — refusing to apply a plan whose preconditions no longer hold", live.GetResourceVersion(), plan.ResourceVersion)
	}
	liveImage, found, err := podTemplateContainerImage(live, params.Container)
	if err != nil {
		return nil, false, err
	}
	if !found {
		return nil, false, fmt.Errorf("no container named %q on the live object — refusing to execute, because a strategic-merge patch keyed on an unmatched container name would ADD a container rather than change one", params.Container)
	}
	// Ordered before the rollback comparison deliberately: both conditions catch
	// the same class of situation (the hub's view of live state is out of date),
	// but this one has the answer an operator can act on — "it already runs
	// that image, nothing to do" — while the other would report it as a
	// rollback mismatch and send them looking for a corruption that isn't there.
	if liveImage == params.Image {
		return nil, false, fmt.Errorf("container %q already runs image %s — there is nothing to revert", params.Container, params.Image)
	}
	if liveImage != rollbackParams.Image {
		return nil, false, fmt.Errorf("container %q is running image %s, but this plan's rollback claims it is running %s — refusing to make a change whose recorded undo does not match reality", params.Container, liveImage, rollbackParams.Image)
	}
	if err := e.verifyImageRanInThisWorkload(ctx, live, params.Container, params.Image); err != nil {
		return nil, false, err
	}

	patch, err := json.Marshal(map[string]any{
		"metadata": map[string]any{"resourceVersion": plan.ResourceVersion},
		"spec": map[string]any{
			"template": map[string]any{
				"spec": map[string]any{
					"containers": []any{
						map[string]any{
							"name":  params.Container,
							"image": params.Image,
						},
					},
				},
			},
		},
	})
	if err != nil {
		return nil, false, fmt.Errorf("build patch: %w", err)
	}

	patched, err := e.applyPlanPatch(ctx, gvr, plan, patch)
	if err != nil {
		return nil, false, sanitizeK8sErr(err)
	}
	return planPatchResult(plan, patched, patch), false, nil
}

// verifyImageRanInThisWorkload is check (4) above: the image must appear as
// this container's image in at least one ReplicaSet owned by this exact
// Deployment.
//
// Ownership is established by ownerReference UID, never by the
// `<deployment>-<hash>` name prefix a human reads a `kubectl get rs` listing
// with — a UID cannot be produced by an unrelated object that happens to be
// named suggestively, and a name prefix can. The list is namespace-scoped and
// uses the same read grant every other read in this file relies on.
//
// Fails closed on every uncertain path, including a failed List: "we could not
// read the history" must never be treated as "the history is fine". The cost of
// that strictness is that an image revert is unavailable while the API server
// is refusing list calls, which is the right trade for the one check standing
// between a compromised hub and an arbitrary image.
//
// What it deliberately does NOT check: whether the image belongs to the
// IMMEDIATELY previous revision, or to the highest-numbered non-current one.
// That selection is the hub's, made against the same history plus rules an
// operator approved (internal/api/remediation_exec.go's resolvePreviousImage),
// and re-deriving it here would mean two implementations of "which revision is
// previous" that have to agree forever — the exact drift
// verifyLiveContainerResources avoids by asking a different question rather
// than the same one twice.
func (e *ToolExecutor) verifyImageRanInThisWorkload(ctx context.Context, deployment *unstructured.Unstructured, container, image string) error {
	ownerUID := deployment.GetUID()
	if ownerUID == "" {
		return errors.New("the target Deployment has no UID — refusing to verify a revert target against a rollout history whose ownership cannot be established")
	}

	list, err := e.dynamic.Resource(replicaSetGVR).Namespace(deployment.GetNamespace()).List(ctx, metav1.ListOptions{})
	if err != nil {
		logger.WarnContext(ctx, "revert_container_image: listing ReplicaSets to verify the revert target failed", slog.String("namespace", deployment.GetNamespace()), logging.Err(err))
		return errors.New("could not read this workload's rollout history (its ReplicaSets) to verify the requested image ever ran here — refusing to change a container's image without that check")
	}

	for i := range list.Items {
		rs := &list.Items[i]
		owned := false
		for _, ref := range rs.GetOwnerReferences() {
			if ref.UID == ownerUID {
				owned = true
				break
			}
		}
		if !owned {
			continue
		}
		rsImage, found, err := podTemplateContainerImage(rs, container)
		if err != nil {
			// A single unreadable ReplicaSet is not fatal to the check: it
			// cannot make an image look verified, only fail to verify it, and
			// another revision may still hold the answer. Logged so that a
			// systematically malformed history is visible rather than silently
			// narrowing this check's coverage.
			logger.WarnContext(ctx, "revert_container_image: skipping ReplicaSet while verifying the revert target", slog.String("namespace", rs.GetNamespace()), slog.String("name", rs.GetName()), logging.Err(err))
			continue
		}
		if found && rsImage == image {
			return nil
		}
	}

	return fmt.Errorf("image %s does not appear as container %q's image in any ReplicaSet this workload owns, so ARGUS cannot show it ever ran here — refusing to set an image that is not in this workload's own rollout history", image, container)
}

// podTemplateContainerImage reads one named container's image out of any object
// carrying a pod template — a Deployment or one of its ReplicaSets, which have
// the identical /spec/template/spec/containers shape. The three-valued return
// (image, found, error) keeps apart the two answers that must not be conflated:
// "this object's template has no such container" is ordinary information when
// walking a rollout history (a container can be added between revisions), while
// "this object's template could not be read" is a refusal. Collapsing them into
// an empty string would let a misread object read as a container that simply
// isn't there — and, in the caller above, silently narrow the set of history
// this check covers.
func podTemplateContainerImage(obj *unstructured.Unstructured, container string) (image string, found bool, err error) {
	containers, ok, err := unstructured.NestedSlice(obj.Object, "spec", "template", "spec", "containers")
	if err != nil || !ok {
		return "", false, fmt.Errorf("%s %s/%s has no readable spec.template.spec.containers", obj.GetKind(), obj.GetNamespace(), obj.GetName())
	}
	for _, raw := range containers {
		c, ok := raw.(map[string]any)
		if !ok {
			return "", false, fmt.Errorf("%s %s/%s has a malformed container entry", obj.GetKind(), obj.GetNamespace(), obj.GetName())
		}
		if name, _ := c["name"].(string); name != container {
			continue
		}
		img, ok := c["image"].(string)
		if !ok || img == "" {
			return "", false, fmt.Errorf("container %q on %s %s/%s has no readable image", container, obj.GetKind(), obj.GetNamespace(), obj.GetName())
		}
		return img, true, nil
	}
	return "", false, nil
}

// restartPod implements lld/08 §3's restartWorkload: a strategic-merge
// Patch setting /spec/template/metadata/annotations/argus.io~1restartedAt
// (the tilde-escape is a JSONPatch-pointer detail; a strategic-merge patch
// body just nests the map directly), with the same embedded-resourceVersion
// precondition as scaleDeployment. Despite this action type's name, the
// target this actually patches is the owning Deployment/StatefulSet/
// DaemonSet, never a bare Pod — see restartablePodTemplateKinds' own doc
// comment for why resolving "which workload owns this Pod" is
// internal/api/approvals.go's job, not this tool call's.
func (e *ToolExecutor) restartPod(ctx context.Context, rawArgs json.RawMessage) (json.RawMessage, bool, error) {
	plan, gvr, err := e.verifySignedPlan(rawArgs, remediation.ActionRestartPod)
	if err != nil {
		return nil, false, err
	}
	gvk, err := parseGVKString(plan.TargetGVK)
	if err != nil {
		return nil, false, err
	}
	if !restartablePodTemplateKinds[gvk.Kind] {
		return nil, false, fmt.Errorf("restart_pod requires a target with a pod template (Deployment/StatefulSet/DaemonSet); got kind %q — the owning workload must be resolved before signing this plan", gvk.Kind)
	}

	patch, err := json.Marshal(map[string]any{
		"metadata": map[string]any{"resourceVersion": plan.ResourceVersion},
		"spec": map[string]any{
			"template": map[string]any{
				"metadata": map[string]any{
					"annotations": map[string]any{
						"argus.io/restartedAt": time.Now().UTC().Format(time.RFC3339),
					},
				},
			},
		},
	})
	if err != nil {
		return nil, false, fmt.Errorf("build patch: %w", err)
	}

	patched, err := e.applyPlanPatch(ctx, gvr, plan, patch)
	if err != nil {
		return nil, false, sanitizeK8sErr(err)
	}
	return planPatchResult(plan, patched, patch), false, nil
}
